import{_ as i,C as r,o as t,c as o,a3 as a,b as d,w as n,a as l,E as p,a4 as c}from"./chunks/framework.BTQ4eCVb.js";const y=JSON.parse('{"title":"WhatsApp Cloud Integration","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"WhatsApp Cloud Integration | EloSync Docs"}],["meta",{"property":"og:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"property":"og:url","content":"https://docs.elosync.com/developer-guide/whatsapp-cloud-integration"}],["meta",{"property":"og:image","content":"https://docs.elosync.com/og-image.svg"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"WhatsApp Cloud Integration | EloSync Docs"}],["meta",{"name":"twitter:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"name":"twitter:image","content":"https://docs.elosync.com/og-image.svg"}],["link",{"rel":"canonical","href":"https://docs.elosync.com/developer-guide/whatsapp-cloud-integration"}]]},"headers":[],"relativePath":"developer-guide/whatsapp-cloud-integration.md","filePath":"developer-guide/whatsapp-cloud-integration.md","lastUpdated":1788201759000}'),h={name:"developer-guide/whatsapp-cloud-integration.md"};function u(m,e,g,b,v,f){const s=r("Mermaid");return t(),o("div",null,[e[1]||(e[1]=a(`<h1 id="whatsapp-cloud-integration" tabindex="-1">WhatsApp Cloud Integration <a class="header-anchor" href="#whatsapp-cloud-integration" aria-label="Permalink to &quot;WhatsApp Cloud Integration&quot;">​</a></h1><blockquote><p><strong>Status: Shipped 1.3.0</strong> — billable Marketplace module <code>whatsapp-cloud</code>.</p><p>Includes: Meta WABA/phone connect, text + media send/receive, shared inbox, Lead soft link, Meta Cloud template sync + outside-24h enforcement, opt-in WhatsApp Lead Source Driver, Automation <code>whatsapp.message_received</code> / <code>send_whatsapp_template</code>. Deferred: interactive buttons/lists, alternate BSPs.</p><p>Follow the <a href="/architecture/module-architecture">Module Architecture</a>, <a href="/developer-guide/module-development">Module Development Standard</a>, <a href="/developer-guide/documentation-governance">Documentation Governance</a> same-PR rule, and the frozen <a href="/developer-guide/notification-architecture-contract">Notification Architecture Contract</a>.</p></blockquote><hr><h2 id="purpose" tabindex="-1">Purpose <a class="header-anchor" href="#purpose" aria-label="Permalink to &quot;Purpose&quot;">​</a></h2><p>Evolve EloSync from a <strong>manual WhatsApp handoff</strong> (<code>wa.me</code>) into a complete <strong>WhatsApp communication platform</strong> built on the official <strong>WhatsApp Cloud API</strong>, while keeping business logic inside EloSync and provider specifics inside replaceable drivers.</p><p><strong>Shipped through 1.3.0:</strong></p><ul><li>Connect tenant WhatsApp Business Accounts and phone numbers via Meta</li><li>Send and receive <strong>text and media</strong> through EloSync (not the user’s personal WhatsApp client)</li><li>Shared inbox, Meta Cloud templates, delivery/read status webhooks</li><li>Soft-link conversations to Leads; mirror messages on the Lead timeline</li><li>Opt-in WhatsApp Lead Source Driver (<code>auto_create_leads</code>, default off)</li><li>Automation trigger <code>whatsapp.message_received</code> and action <code>send_whatsapp_template</code></li><li>Notifications for inbound / send failed / needs reauth</li></ul><p><strong>Still deferred:</strong></p><ul><li>Interactive buttons / lists, alternate BSPs, AI WhatsApp features</li><li>Replacing Communication Templates’ <code>wa.me</code> (kept as fallback when Cloud is not ready)</li><li>Making WhatsApp the only messaging channel forever (drivers must stay replaceable)</li></ul><hr><h2 id="current-state" tabindex="-1">Current state <a class="header-anchor" href="#current-state" aria-label="Permalink to &quot;Current state&quot;">​</a></h2><h3 id="whatsapp-cloud-whatsapp-cloud-—-shipped-1-3-0" tabindex="-1">WhatsApp Cloud (<code>whatsapp-cloud</code>) — shipped 1.3.0 <a class="header-anchor" href="#whatsapp-cloud-whatsapp-cloud-—-shipped-1-3-0" aria-label="Permalink to &quot;WhatsApp Cloud (\`whatsapp-cloud\`) — shipped 1.3.0&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Shipped</th><th>Behavior</th></tr></thead><tbody><tr><td>Marketplace module</td><td>Billable CRM slug <code>whatsapp-cloud</code> ($29 / $290)</td></tr><tr><td>Connect</td><td>Meta OAuth → WABA → phone; webhook subscribe; encrypted tokens</td></tr><tr><td>Inbox</td><td>Shared conversation list + thread; text + media send/receive</td></tr><tr><td>Templates</td><td>Sync Meta Cloud templates; required outside the 24h window</td></tr><tr><td>Lead soft link</td><td>Manual <code>lead_id</code>; timeline via Lead APIs</td></tr><tr><td>Lead Source</td><td>Opt-in <code>auto_create_leads</code> + <code>default_lead_source</code></td></tr><tr><td>Automation</td><td>Soft dep: <code>whatsapp.message_received</code> / <code>send_whatsapp_template</code></td></tr><tr><td>Notifications</td><td>Inbound, send failed, needs reauth</td></tr></tbody></table><p>Canonical user docs: <a href="/user-guide/whatsapp-cloud">WhatsApp Cloud</a> · <a href="/api/tenant-v1-whatsapp-cloud">API</a> · <a href="/deployment/whatsapp-cloud">Deploy</a>.</p><h3 id="communication-templates-fallback-wa-me" tabindex="-1">Communication Templates fallback (<code>wa.me</code>) <a class="header-anchor" href="#communication-templates-fallback-wa-me" aria-label="Permalink to &quot;Communication Templates fallback (\`wa.me\`)&quot;">​</a></h3><p>EloSync <strong>also</strong> supports a lightweight WhatsApp handoff via <a href="/developer-guide/communication-templates">Communication Templates</a>:</p><table tabindex="0"><thead><tr><th>Fallback</th><th>Behavior</th></tr></thead><tbody><tr><td>WhatsApp button on Lead pages</td><td>Shown when Communication Templates is installed and Cloud is not ready / not entitled</td></tr><tr><td>Opens <code>wa.me</code> / WhatsApp Desktop / WhatsApp Web</td><td>API returns <code>wa_me_url</code>; the browser opens it</td></tr><tr><td>User manually sends messages</td><td>The agent completes send inside WhatsApp; EloSync does not transmit the message</td></tr></tbody></table><h3 id="deferred" tabindex="-1">Deferred <a class="header-anchor" href="#deferred" aria-label="Permalink to &quot;Deferred&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Capability</th><th>Status</th></tr></thead><tbody><tr><td>Interactive buttons / lists</td><td>⬜ Deferred</td></tr><tr><td>Alternate BSPs (Twilio / 360dialog)</td><td>⬜ Deferred</td></tr><tr><td>AI Features</td><td>⬜ Deferred</td></tr></tbody></table><h3 id="post-mvp-polish-shipped" tabindex="-1">Post-MVP polish (shipped) <a class="header-anchor" href="#post-mvp-polish-shipped" aria-label="Permalink to &quot;Post-MVP polish (shipped)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Capability</th><th>Status</th></tr></thead><tbody><tr><td>Media upload/download</td><td>✅ Shipped (1.3.0)</td></tr><tr><td>Automation WhatsApp triggers/actions</td><td>✅ Shipped (1.2.0 / automation 1.1.0)</td></tr><tr><td>WhatsApp Lead Source Driver (auto-create Leads)</td><td>✅ Shipped (opt-in <code>auto_create_leads</code>)</td></tr></tbody></table><hr><h2 id="vision" tabindex="-1">Vision <a class="header-anchor" href="#vision" aria-label="Permalink to &quot;Vision&quot;">​</a></h2><p>EloSync should become a complete WhatsApp communication platform on the official WhatsApp Cloud API.</p><p>Future capabilities include:</p><ul><li>Connect WhatsApp Business Account</li><li>Multiple phone numbers</li><li>Multiple business accounts</li><li>Send messages</li><li>Receive messages</li><li>Message templates (Meta-approved Cloud API templates)</li><li>Media support</li><li>Contact synchronization</li><li>Conversation history</li><li>Shared inbox</li><li>Team assignment</li><li>Internal notes</li><li>Automation</li><li>Campaign messaging</li><li>Activity timeline</li><li>Notifications</li></ul><p>The existing <code>wa.me</code> flow remains a valid fallback until Cloud API connect + send is production-ready for a tenant.</p><hr><h2 id="architecture" tabindex="-1">Architecture <a class="header-anchor" href="#architecture" aria-label="Permalink to &quot;Architecture&quot;">​</a></h2><h3 id="outgoing-high-level" tabindex="-1">Outgoing (high level) <a class="header-anchor" href="#outgoing-high-level" aria-label="Permalink to &quot;Outgoing (high level)&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Lead</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>Conversation</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>Messaging Service</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>WhatsApp Driver</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>WhatsApp Cloud API</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>Meta</span></span></code></pre></div><h3 id="incoming-high-level" tabindex="-1">Incoming (high level) <a class="header-anchor" href="#incoming-high-level" aria-label="Permalink to &quot;Incoming (high level)&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Meta Webhook</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>Webhook Verification</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>WhatsApp Driver</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>Conversation Service</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>Lead Activity</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>Notifications</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>Automation</span></span></code></pre></div><h3 id="component-map-planned" tabindex="-1">Component map (planned) <a class="header-anchor" href="#component-map-planned" aria-label="Permalink to &quot;Component map (planned)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Component</th><th>Responsibility</th></tr></thead><tbody><tr><td>Messaging Service</td><td>Provider-agnostic send/receive orchestration, queueing, retries</td></tr><tr><td>Conversation Service</td><td>Thread lifecycle, assignment, inbox queries, link to Lead</td></tr><tr><td><code>WhatsAppCloudDriver</code></td><td>Cloud API auth, webhooks, templates, media, status mapping</td></tr><tr><td>Lead module</td><td>Lead ownership, timeline/activity hooks via <code>LeadService</code> / activity services — not Graph parsing</td></tr><tr><td>Notification system</td><td>In-app / mail digests per <a href="/developer-guide/notification-architecture-contract">Notification Architecture Contract</a></td></tr><tr><td>Automation Engine</td><td>Domain-event workflows (<code>automation</code> module); WhatsApp <code>whatsapp.message_received</code> + <code>send_whatsapp_template</code> shipped in automation <strong>1.1.0</strong> / WA <strong>1.2.0</strong></td></tr></tbody></table><p>Business rules (who may send, assignment, logging, automation) stay in EloSync. Drivers only speak to external providers.</p><hr><h2 id="driver-architecture" tabindex="-1">Driver architecture <a class="header-anchor" href="#driver-architecture" aria-label="Permalink to &quot;Driver architecture&quot;">​</a></h2><p>WhatsApp follows the platform <strong>driver</strong> pattern (same Open/Closed idea as payment gateways, email drivers, and <a href="/developer-guide/lead-source-driver-architecture">Lead Source Driver Architecture</a>).</p><h3 id="messaging-provider-driver" tabindex="-1">Messaging provider driver <a class="header-anchor" href="#messaging-provider-driver" aria-label="Permalink to &quot;Messaging provider driver&quot;">​</a></h3><p>Future primary driver:</p><p><strong><code>WhatsAppCloudDriver</code></strong></p><p>Messaging providers should be <strong>replaceable</strong>. Conversation Service and Messaging Service depend on a messaging-driver contract — not on Meta SDK types leaking into controllers or Lead models.</p><table tabindex="0"><thead><tr><th>Future messaging driver</th><th>Role</th></tr></thead><tbody><tr><td>WhatsApp Cloud</td><td>Official Meta Cloud API (primary)</td></tr><tr><td>Twilio WhatsApp</td><td>Alternate BSP / Twilio channel</td></tr><tr><td>360dialog</td><td>BSP adapter</td></tr><tr><td>Infobip</td><td>BSP adapter</td></tr><tr><td>MessageBird</td><td>BSP adapter</td></tr></tbody></table><p>Drivers only communicate with external providers. They must <strong>not</strong> own assignment, inbox permissions, Lead business rules, or notification fan-out.</p><h3 id="lead-source-driver-related-separate-concern" tabindex="-1">Lead Source Driver (related, separate concern) <a class="header-anchor" href="#lead-source-driver-related-separate-concern" aria-label="Permalink to &quot;Lead Source Driver (related, separate concern)&quot;">​</a></h3><p>Inbound WhatsApp can also create or enrich leads (e.g. first message from an unknown number). That path uses the <a href="/developer-guide/lead-source-driver-architecture">Lead Source Driver Architecture</a> catalog entry <strong>WhatsApp Driver</strong> → <code>NormalizedLeadData</code> → <code>LeadDuplicateService</code> → <code>LeadService</code>.</p><table tabindex="0"><thead><tr><th>Concern</th><th>Driver family</th></tr></thead><tbody><tr><td>Send/receive messages, status, media</td><td>Messaging drivers (<code>WhatsAppCloudDriver</code>, …)</td></tr><tr><td>Turn an inbound contact into a Lead</td><td>Lead Source Driver (WhatsApp)</td></tr></tbody></table><p>Do not collapse both into a single class that writes Leads and messages directly.</p><hr><h2 id="authentication" tabindex="-1">Authentication <a class="header-anchor" href="#authentication" aria-label="Permalink to &quot;Authentication&quot;">​</a></h2><p>Documented Meta / OAuth-style onboarding (planned):</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Tenant</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>Connect Meta</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>Select Business</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>Select WhatsApp Business Account</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>Select Phone Number</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>Store encrypted tokens</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>Subscribe Webhooks</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>Ready</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Operation</th><th>Behavior</th></tr></thead><tbody><tr><td><strong>Reconnect</strong></td><td>Re-run OAuth; refresh tokens; re-select WABA / phone if needed; re-subscribe webhooks; mark healthy</td></tr><tr><td><strong>Disconnect</strong></td><td>Unsubscribe webhooks where possible; clear encrypted tokens; leave historical conversations/messages intact</td></tr><tr><td><strong>Token refresh</strong></td><td>Refresh before expiry; on failure mark <code>needs_reauth</code> and pause outbound/inbound processing for that number</td></tr></tbody></table><p>Central holds the platform Meta App configuration. Each tenant owns its own connection, WABA selection, phone numbers, and encrypted secrets (same secret-handling patterns as payment / mail / Meta Lead Ads).</p><hr><h2 id="multi-tenant-design" tabindex="-1">Multi-tenant design <a class="header-anchor" href="#multi-tenant-design" aria-label="Permalink to &quot;Multi-tenant design&quot;">​</a></h2><p>Each tenant owns:</p><table tabindex="0"><thead><tr><th>Tenant-owned asset</th><th>Notes</th></tr></thead><tbody><tr><td>Meta connection</td><td>OAuth / embedded signup linkage</td></tr><tr><td>Business Account</td><td>Selected Meta Business / WABA</td></tr><tr><td>Phone numbers</td><td>One or more WhatsApp Business phone numbers</td></tr><tr><td>Templates</td><td>Synced Meta message templates for that WABA</td></tr><tr><td>Tokens</td><td>Encrypted access tokens / secrets</td></tr><tr><td>Webhook subscriptions</td><td>Per-number or app-level subscription state scoped to the tenant</td></tr></tbody></table><p><strong>No tenant data may be shared.</strong> Shared webhook ingress must resolve the tenant by phone number ID / WABA identifier (or equivalent Meta routing key) <strong>before</strong> Conversation Service runs. Enforce uniqueness of phone number ID → tenant at connect time.</p><hr><h2 id="messaging-flow" tabindex="-1">Messaging flow <a class="header-anchor" href="#messaging-flow" aria-label="Permalink to &quot;Messaging flow&quot;">​</a></h2><h3 id="outgoing" tabindex="-1">Outgoing <a class="header-anchor" href="#outgoing" aria-label="Permalink to &quot;Outgoing&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Lead</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>Compose Message</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>Conversation Service</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>WhatsApp Driver</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>Meta API</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>Customer</span></span></code></pre></div><h3 id="incoming" tabindex="-1">Incoming <a class="header-anchor" href="#incoming" aria-label="Permalink to &quot;Incoming&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Customer</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>Meta Webhook</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>Driver</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>Conversation Service</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>Lead Timeline</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>Notification</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>Automation</span></span></code></pre></div><h3 id="sequence-conceptual" tabindex="-1">Sequence (conceptual) <a class="header-anchor" href="#sequence-conceptual" aria-label="Permalink to &quot;Sequence (conceptual)&quot;">​</a></h3>`,67)),(t(),d(c,null,{default:n(()=>[p(s,{id:"mermaid-721",class:"mermaid",graph:"sequenceDiagram%0A%20%20participant%20Agent%20as%20Tenant%20Agent%0A%20%20participant%20Conv%20as%20Conversation%20Service%0A%20%20participant%20Msg%20as%20Messaging%20Service%0A%20%20participant%20Drv%20as%20WhatsAppCloudDriver%0A%20%20participant%20Meta%20as%20WhatsApp%20Cloud%20API%0A%20%20participant%20Cust%20as%20Customer%0A%20%20participant%20WH%20as%20Webhook%20Endpoint%0A%20%20participant%20Lead%20as%20Lead%20Activity%20%2F%20Timeline%0A%20%20participant%20N%20as%20Notifications%20%2F%20Automations%0A%0A%20%20Agent-%3E%3EConv%3A%20Compose%20on%20Lead-linked%20conversation%0A%20%20Conv-%3E%3EMsg%3A%20Send%20request%0A%20%20Msg-%3E%3EDrv%3A%20Driver%20send%0A%20%20Drv-%3E%3EMeta%3A%20Cloud%20API%20message%0A%20%20Meta-%3E%3ECust%3A%20Deliver%0A%20%20Cust-%3E%3EMeta%3A%20Reply%0A%20%20Meta-%3E%3EWH%3A%20Webhook%0A%20%20WH-%3E%3EDrv%3A%20Verify%20signature%20%2B%20parse%0A%20%20Drv-%3E%3EConv%3A%20Inbound%20message%0A%20%20Conv-%3E%3ELead%3A%20Timeline%20%2F%20activity%0A%20%20Conv-%3E%3EN%3A%20New%20message%20notification%20%2B%20automation%20hooks%0A"})]),fallback:n(()=>[...e[0]||(e[0]=[l(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=a(`<hr><h2 id="conversation-model" tabindex="-1">Conversation model <a class="header-anchor" href="#conversation-model" aria-label="Permalink to &quot;Conversation model&quot;">​</a></h2><p>Conceptual entities only — not a finalized schema.</p><table tabindex="0"><thead><tr><th>Entity</th><th>Intent</th></tr></thead><tbody><tr><td><strong>Conversations</strong></td><td>Thread between a tenant phone number and a customer WhatsApp identity</td></tr><tr><td><strong>Messages</strong></td><td>Individual inbound/outbound items with type, body, status, timestamps</td></tr><tr><td><strong>Attachments</strong></td><td>Media references (prefer encrypted / storage refs; avoid unbounded blob storage in DB)</td></tr><tr><td><strong>Participants</strong></td><td>Customer + tenant agents involved</td></tr><tr><td><strong>Statuses</strong></td><td>Queued → sent → delivered → read / failed / expired</td></tr><tr><td><strong>Assignments</strong></td><td>Which agent/team owns the conversation</td></tr><tr><td><strong>Internal Notes</strong></td><td>Agent-only notes not sent to WhatsApp</td></tr><tr><td><strong>Conversation Labels</strong></td><td>Tags for inbox filtering and routing</td></tr></tbody></table><p>Exact table names, UUIDs, and indexes are deferred to the implementation PR. Prefer linking <code>conversation.lead_id</code> (nullable) rather than duplicating Lead contact fields.</p><hr><h2 id="message-types" tabindex="-1">Message types <a class="header-anchor" href="#message-types" aria-label="Permalink to &quot;Message types&quot;">​</a></h2><p>Support roadmap:</p><table tabindex="0"><thead><tr><th>Type</th><th>Notes</th></tr></thead><tbody><tr><td>Text</td><td>Default body</td></tr><tr><td>Image</td><td>Media download/upload via driver</td></tr><tr><td>Video</td><td>Media</td></tr><tr><td>Audio</td><td>Media / voice notes</td></tr><tr><td>Document</td><td>Files</td></tr><tr><td>Sticker</td><td>Stickers</td></tr><tr><td>Location</td><td>Lat/long + optional name</td></tr><tr><td>Contacts</td><td>Shared contact cards</td></tr><tr><td>Interactive Buttons</td><td>Reply buttons</td></tr><tr><td>Lists</td><td>List messages</td></tr><tr><td>Template Messages</td><td>Meta-approved templates outside the 24h session window</td></tr></tbody></table><p>Drivers map provider payloads into a common internal message type enum; UI and Conversation Service consume the common type.</p><hr><h2 id="message-status" tabindex="-1">Message status <a class="header-anchor" href="#message-status" aria-label="Permalink to &quot;Message status&quot;">​</a></h2><p>Future support for delivery lifecycle:</p><table tabindex="0"><thead><tr><th>Status</th><th>Meaning</th></tr></thead><tbody><tr><td>Queued</td><td>Accepted by EloSync; not yet accepted by Meta</td></tr><tr><td>Sent</td><td>Accepted by Cloud API</td></tr><tr><td>Delivered</td><td>Delivered to customer device</td></tr><tr><td>Read</td><td>Read receipt (when available)</td></tr><tr><td>Failed</td><td>Permanent or terminal failure</td></tr><tr><td>Expired</td><td>Expired per Meta / session rules</td></tr></tbody></table><p>Status webhooks update the Message entity idempotently (by Meta message ID). Drivers translate provider statuses; Conversation Service persists them.</p><hr><h2 id="lead-integration" tabindex="-1">Lead integration <a class="header-anchor" href="#lead-integration" aria-label="Permalink to &quot;Lead integration&quot;">​</a></h2><p>Every conversation should be linked to a <strong>Lead</strong> whenever possible (match by phone / prior thread / explicit agent link).</p><p>Messages should automatically appear inside:</p><ul><li>Lead Timeline</li><li>Activities</li><li>Future Communication History</li></ul><table tabindex="0"><thead><tr><th>Rule</th><th>Detail</th></tr></thead><tbody><tr><td>Write path</td><td>Lead activity / timeline updates go through Lead-owned services — not raw inserts from the WhatsApp driver</td></tr><tr><td>Unknown numbers</td><td>May create or attach a Lead via the WhatsApp <strong>Lead Source Driver</strong> + <code>LeadService</code></td></tr><tr><td>Independence</td><td>Messaging can exist without Meta Lead Ads; Lead Ads can exist without WhatsApp Cloud</td></tr></tbody></table><hr><h2 id="templates" tabindex="-1">Templates <a class="header-anchor" href="#templates" aria-label="Permalink to &quot;Templates&quot;">​</a></h2><p>Two template concepts must stay distinct:</p><table tabindex="0"><thead><tr><th>Kind</th><th>Today / future</th></tr></thead><tbody><tr><td><strong>Communication Templates</strong> (shipped)</td><td>Tenant plain-text snippets for <code>wa.me</code> handoff</td></tr><tr><td><strong>WhatsApp Cloud templates</strong> (future)</td><td>Meta-approved templates synced from WABA</td></tr></tbody></table><p>Future Cloud template support:</p><ul><li>Sync Meta templates into the tenant</li><li>Approval status (pending / approved / rejected)</li><li>Languages</li><li>Variables / placeholders</li><li>Categories (utility, marketing, authentication — per Meta rules)</li></ul><p>Sending outside the customer service window requires an approved Cloud template. Communication Templates may later feed copy into Cloud template variables, but they are not the same store.</p><hr><h2 id="automation" tabindex="-1">Automation <a class="header-anchor" href="#automation" aria-label="Permalink to &quot;Automation&quot;">​</a></h2><p>Future examples for <strong>WhatsApp message</strong> triggers (CRM domain-event Automation ships as Marketplace module <code>automation</code>; message events wait on Cloud API):</p><ul><li>Send welcome message</li><li>Follow-up reminders</li><li>Missed appointment reminder</li><li>Payment reminder</li><li>Birthday greeting</li><li>Drip campaigns</li><li>Workflow automation (if message received → create Task / change Lead stage)</li></ul><p>Automations subscribe to Conversation / Message domain events. Drivers do not embed business workflows. See <a href="/developer-guide/automation">Automation developer guide</a>.</p><hr><h2 id="notifications" tabindex="-1">Notifications <a class="header-anchor" href="#notifications" aria-label="Permalink to &quot;Notifications&quot;">​</a></h2><p>Future notifications include:</p><ul><li>New incoming message</li><li>Unread conversations</li><li>Failed delivery</li><li>Template rejection</li></ul><p>Integrate with the existing notification system (<a href="/developer-guide/notification-architecture-contract">Notification Architecture Contract</a>): additive <code>type</code> / <code>metadata</code> / <code>source</code> fields; Reverb fan-out where <code>broadcast_ready</code>; no parallel notification framework.</p><hr><h2 id="security" tabindex="-1">Security <a class="header-anchor" href="#security" aria-label="Permalink to &quot;Security&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Control</th><th>Requirement</th></tr></thead><tbody><tr><td>Webhook signature verification</td><td>Verify Meta/<code>X-Hub-Signature-256</code> (or current Meta WhatsApp signature scheme) before trusted processing</td></tr><tr><td>Encrypted tokens</td><td>WABA / phone tokens encrypted at rest; APIs return masks only</td></tr><tr><td>Encrypted media references</td><td>Store storage keys / signed URLs carefully; do not log raw media binaries</td></tr><tr><td>Queue processing</td><td>Acknowledge webhooks quickly; process on a dedicated queue</td></tr><tr><td>Rate limiting</td><td>Throttle outbound Cloud API calls; respect Meta rate limits</td></tr><tr><td>Idempotent webhook handling</td><td>Deduplicate by Meta message / status IDs</td></tr><tr><td>Audit logging</td><td>Platform audit for connect/disconnect, send failures, permission changes</td></tr><tr><td>Permission checks</td><td>Tenant RBAC for inbox, send, manage connection, manage templates</td></tr></tbody></table><p>CSRF-exempt webhook route under a narrow prefix (same operational pattern as payment / email / Meta Lead Ads webhooks).</p><hr><h2 id="error-handling" tabindex="-1">Error handling <a class="header-anchor" href="#error-handling" aria-label="Permalink to &quot;Error handling&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Scenario</th><th>Expected behavior</th></tr></thead><tbody><tr><td>Expired tokens</td><td>Mark connection <code>needs_reauth</code>; pause send/receive for affected numbers; alert tenant admins</td></tr><tr><td>Revoked permissions</td><td>Same as expired tokens; surface which scope failed</td></tr><tr><td>Deleted phone numbers</td><td>Mark number unhealthy; stop routing; keep history</td></tr><tr><td>Rate limiting</td><td>Back off; queue outbound; surface soft errors to agents</td></tr><tr><td>Webhook retries</td><td>Idempotent processing; prefer 2xx after durable claim</td></tr><tr><td>Duplicate webhooks</td><td>No duplicate Message rows</td></tr><tr><td>Temporary Meta outages</td><td>Retry with backoff; dead-letter after exhaustion</td></tr><tr><td>Dead-letter queues</td><td>Operator visibility + manual replay</td></tr><tr><td>Retry strategy</td><td>Exponential backoff; distinguish transient vs permanent Graph errors</td></tr></tbody></table><hr><h2 id="permissions-meta-platform" tabindex="-1">Permissions (Meta platform) <a class="header-anchor" href="#permissions-meta-platform" aria-label="Permalink to &quot;Permissions (Meta platform)&quot;">​</a></h2><p>Future production requirements (Meta side):</p><ul><li>Business Verification</li><li>App Review</li><li>WhatsApp Business Account</li><li>Phone Number verification</li><li>Appropriate WhatsApp Cloud API permissions / products enabled on the Meta App</li></ul><p>Local development may use Meta test numbers / development mode without full public Live Mode access. Document tunnel + webhook verify token setup at implementation time.</p><p>Tenant RBAC permissions (EloSync side) are TBD at implementation (e.g. inbox view/send, connection manage) and must follow <code>module:</code> + <code>can:</code> conventions.</p><hr><h2 id="future-enhancements" tabindex="-1">Future enhancements <a class="header-anchor" href="#future-enhancements" aria-label="Permalink to &quot;Future enhancements&quot;">​</a></h2><p>Placeholders after core Cloud send/receive and inbox:</p><table tabindex="0"><thead><tr><th>Enhancement</th><th>Intent</th></tr></thead><tbody><tr><td>AI auto replies</td><td>Optional AI responses</td></tr><tr><td>AI message summaries</td><td>Thread summaries for agents</td></tr><tr><td>Suggested replies</td><td>Agent assist</td></tr><tr><td>Sentiment analysis</td><td>Conversation scoring</td></tr><tr><td>Voice transcription</td><td>Voice notes → text</td></tr><tr><td>Conversation analytics</td><td>Volume, response time, outcomes</td></tr><tr><td>Broadcast campaigns</td><td>Opt-in bulk messaging within Meta rules</td></tr><tr><td>Chatbot builder</td><td>Visual flows on top of Conversation Service</td></tr><tr><td>Multi-agent inbox</td><td>Concurrent agents, presence</td></tr><tr><td>Team workload balancing</td><td>Assignment algorithms</td></tr><tr><td>CRM triggers</td><td>Stage/status changes from message events</td></tr><tr><td>Calendar integration</td><td>Book from chat (<a href="/getting-started/product-roadmap">Meetings</a> dependency when relevant)</td></tr><tr><td>Task creation from messages</td><td>Create Tasks from a thread</td></tr><tr><td>Voice notes transcription</td><td>Same as voice transcription track</td></tr></tbody></table><p>AI features remain <strong>optional</strong> integrations per <a href="/architecture/module-dependencies">Module Dependencies</a>.</p><hr><h2 id="relationship-with-meta-lead-ads" tabindex="-1">Relationship with Meta Lead Ads <a class="header-anchor" href="#relationship-with-meta-lead-ads" aria-label="Permalink to &quot;Relationship with Meta Lead Ads&quot;">​</a></h2><p><a href="/developer-guide/meta-lead-ads-integration">Meta Lead Ads</a> and WhatsApp Cloud are <strong>complementary</strong>, not substitutes.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Meta Lead Ads</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>Lead</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>Lead Service</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>Conversation</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>WhatsApp Cloud</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Integration</th><th>Job</th></tr></thead><tbody><tr><td>Meta Lead Ads</td><td>Ingest form submissions → Lead (<code>MetaLeadAdsDriver</code> + Lead Source pipeline)</td></tr><tr><td>WhatsApp Cloud</td><td>Communicate with the customer on WhatsApp (<code>WhatsAppCloudDriver</code> + Conversation Service)</td></tr></tbody></table><p>Lead generation and customer communication remain <strong>independent</strong> modules/capabilities connected through the <strong>Lead</strong> entity. Either can ship without the other. Shared Meta App configuration may be reused at the platform level, but tenant Page tokens (Lead Ads) and WABA/phone tokens (WhatsApp) stay separate connection records.</p><p>Both respect driver boundaries: no Meta parsing inside <code>LeadService</code>; no conversation business rules inside Graph clients.</p><hr><h2 id="relationship-with-lead-source-driver-architecture" tabindex="-1">Relationship with Lead Source Driver Architecture <a class="header-anchor" href="#relationship-with-lead-source-driver-architecture" aria-label="Permalink to &quot;Relationship with Lead Source Driver Architecture&quot;">​</a></h2><ul><li>Messaging: <code>WhatsAppCloudDriver</code> (messaging provider contract).</li><li>Optional lead capture from WhatsApp: catalog <strong>WhatsApp Driver</strong> under <a href="/developer-guide/lead-source-driver-architecture">Lead Source Driver Architecture</a>.</li><li>Never bypass <code>LeadService</code> when creating leads from WhatsApp.</li></ul><hr><h2 id="implementation-checklist-mvp-delivered" tabindex="-1">Implementation checklist (MVP delivered) <a class="header-anchor" href="#implementation-checklist-mvp-delivered" aria-label="Permalink to &quot;Implementation checklist (MVP delivered)&quot;">​</a></h2><h3 id="backend" tabindex="-1">Backend <a class="header-anchor" href="#backend" aria-label="Permalink to &quot;Backend&quot;">​</a></h3><ul><li>[x] Central Meta App settings for WhatsApp Cloud (encrypted secrets, verify token)</li><li>[x] Tenant connect / reconnect / disconnect + encrypted WABA/phone tokens</li><li>[x] <code>WhatsAppCloudDriver</code> + messaging driver registry</li><li>[x] Webhook verify + signature rejection path + tenant resolution by phone/WABA id</li><li>[x] Conversation / Message migrations + services</li><li>[x] Outbound send queue + inbound process queue + idempotency</li><li>[x] Lead timeline / activity integration via Lead-owned services</li><li>[x] Template sync from Meta + outside-24h enforcement</li><li>[x] Notification types for inbound / failed / needs_reauth</li><li>[x] Pest: signature, tenancy, idempotency, no direct Lead DB writes from driver</li></ul><h3 id="frontend" tabindex="-1">Frontend <a class="header-anchor" href="#frontend" aria-label="Permalink to &quot;Frontend&quot;">​</a></h3><ul><li>[x] Connection wizard (Business → WABA → phone)</li><li>[x] Shared inbox + Lead soft-link entry</li><li>[x] Compose send + template picker (Cloud templates)</li><li>[x] Playwright smokes with mocked Cloud API</li></ul><h3 id="docs-ops" tabindex="-1">Docs / ops <a class="header-anchor" href="#docs-ops" aria-label="Permalink to &quot;Docs / ops&quot;">​</a></h3><ul><li>[x] Flip this page from Planned → shipped sections</li><li>[x] User Guide + Deployment webhook/env notes</li><li>[x] CHANGELOG + Product Roadmap status</li></ul><hr><h2 id="implementation-status" tabindex="-1">Implementation status <a class="header-anchor" href="#implementation-status" aria-label="Permalink to &quot;Implementation status&quot;">​</a></h2><h3 id="shipped-mvp-1-0-0" tabindex="-1">Shipped MVP 1.0.0 <a class="header-anchor" href="#shipped-mvp-1-0-0" aria-label="Permalink to &quot;Shipped MVP 1.0.0&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Capability</th><th>Status</th></tr></thead><tbody><tr><td>Open WhatsApp manually (<code>wa.me</code> / Desktop / Web)</td><td>✅ Shipped (Communication Templates fallback)</td></tr><tr><td>Cloud API connect + text send/receive</td><td>✅ Shipped</td></tr><tr><td>Incoming messages</td><td>✅ Shipped</td></tr><tr><td>Shared Inbox</td><td>✅ Shipped</td></tr><tr><td>Templates (Meta Cloud)</td><td>✅ Shipped</td></tr><tr><td>Conversation History</td><td>✅ Shipped</td></tr><tr><td>Delivery Tracking / Read Receipts</td><td>✅ Shipped (webhook statuses)</td></tr><tr><td>Soft Lead link + timeline</td><td>✅ Shipped</td></tr><tr><td>WhatsApp Lead Source Driver (opt-in auto-create)</td><td>✅ Shipped (1.1.0)</td></tr><tr><td>Automation WhatsApp triggers / send template</td><td>✅ Shipped (1.2.0)</td></tr><tr><td>Media (image / document / audio / video)</td><td>✅ Shipped (1.3.0)</td></tr></tbody></table><h3 id="deferred-1" tabindex="-1">Deferred <a class="header-anchor" href="#deferred-1" aria-label="Permalink to &quot;Deferred&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Capability</th><th>Status</th></tr></thead><tbody><tr><td>Interactive buttons / lists</td><td>⬜ Deferred</td></tr><tr><td>AI Features</td><td>⬜ Deferred</td></tr><tr><td>Alternate BSPs</td><td>⬜ Deferred</td></tr></tbody></table><hr><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="/developer-guide/lead-source-driver-architecture">Lead Source Driver Architecture</a></li><li><a href="/developer-guide/meta-lead-ads-integration">Meta Lead Ads Integration</a></li><li><a href="/developer-guide/communication-templates">Communication Templates</a> (<code>wa.me</code> fallback)</li><li><a href="/user-guide/whatsapp-cloud">WhatsApp Cloud — User Guide</a></li><li><a href="/api/tenant-v1-whatsapp-cloud">Tenant WhatsApp Cloud API</a></li><li><a href="/deployment/whatsapp-cloud">WhatsApp Cloud Deployment</a></li><li><a href="/developer-guide/leads">Leads — Developer Guide</a></li><li><a href="/developer-guide/notification-architecture-contract">Notification Architecture Contract</a></li><li><a href="/developer-guide/payment-gateways-webhooks">Payment Gateway Webhooks</a> (ingress / signature patterns)</li><li><a href="/developer-guide/email-webhooks">Email provider webhooks</a> (multi-tenant webhook patterns)</li><li><a href="/getting-started/product-roadmap">Product Roadmap</a></li><li><a href="/architecture/module-architecture">Module Architecture</a></li><li><a href="/architecture/module-dependencies">Module Dependencies</a></li><li><a href="/developer-guide/documentation-governance">Documentation Governance</a></li></ul>`,83))])}const k=i(h,[["render",u]]);export{y as __pageData,k as default};
